async function launchChrome() {
  const profile = mkdtempSync(path.join(tmpdir(), 'kkiit-guide-chrome-'))
  const child = spawn(chromeBinary, [
    '--headless=new', '--no-sandbox', '--disable-gpu', '--hide-scrollbars',
