func validateApprovalPolicy(in *approvalPolicyInput) bool {
	in.ResourceType = strings.TrimSpace(in.ResourceType)
	in.Name = strings.TrimSpace(in.Name)
	if in.ResourceType == "" || in.Name == "" {
		return false
	}
	if in.Priority == 0 {
		in.Priority = 100
	}
	if in.Priority < 1 {
		return false
	}
	if in.Conditions == nil {
